// Guarded by the qualified8A fixture: token-bound server + explicitly isolated
// profile ownership, refusing pre-existing unowned CANDY databases.
import './candy-scope8b-browser.mjs';
import { createProjectStore } from '../../src/persistence/projectStore.js';
import { exportAnalysisHistory, stageAnalysisHistory, decodeHistoryPortable } from '../../src/persistence/analysisHistoryPortability.js';
import { createProjectSession } from '../../src/persistence/projectSession.js';
const store=createProjectStore(), pause=ms=>new Promise(resolve=>setTimeout(resolve,ms??25));
const port=()=>document.querySelector('[data-history-portability-state]'), button=(text,node=document)=>[...node.querySelectorAll('button')].find(b=>b.textContent===text), check=(v,message)=>{if(!v)throw Error(message);};
async function wait(fn,label){for(let n=0;n<1600;n++){const v=await fn();if(v)return v;await pause();}throw Error('8C timeout '+label+' '+document.body.textContent.slice(-1800));}
let fault=null,writeCount=0;const events=[],put=IDBObjectStore.prototype.put,transaction=IDBDatabase.prototype.transaction;
IDBObjectStore.prototype.put=function(value,...args){if(fault?.write&&++writeCount===fault.write)throw new DOMException('8C injected quota at publication write','QuotaExceededError');return put.call(this,value,...args);};
IDBDatabase.prototype.transaction=function(names,mode,...args){const tx=transaction.call(this,names,mode,...args),selected=[...tx.objectStoreNames];if(mode==='readwrite'&&selected.includes('analysisHistories')&&selected.includes('meta')&&!selected.includes('workspaceObjects')){events.push('transaction');tx.addEventListener('complete',()=>events.push('complete'));}return tx;};
async function summary(id){return{project:await store.readProject(id),history:(await store.readAnalysisHistory(id)).envelope,root:(await store.readWorkspace(id)).root,memory:(await store.readMemory(id)).envelope,thread:(await store.load(id)).record,model:await store.readConnectionProfile()};}
async function exportFile(id){const file=await exportAnalysisHistory(store,id??await window.s8b.currentId());return{...file,bytes:undefined,base64:btoa(String.fromCharCode(...file.bytes))};}
async function rawImport(base64,current=true){const stage=await stageAnalysisHistory(Uint8Array.from(atob(base64),c=>c.charCodeAt(0)));try{const receipt=await store.importAnalysisHistory(stage,{isCurrent:()=>current});events.push('receipt');return receipt;}catch(e){return{error:e.code,message:e.message};}}
window.s8c={...window.s8b,ready:true,events,summary,exportFile,rawImport,
 preview(){const node=document.querySelector('[aria-label="History import preview"]');return{present:Boolean(node),images:node?.querySelectorAll('img').length??0};},
 async inventoryCount(){return(await store.listProjects()).length;},
 async selectDurable(id){const p=await store.readResumePreferences();await store.saveResumePreferences(p.revision,{...p,selectedProjectId:id});await window.s8b.reload();return true;},
 async download(){button('Download analysis history',port()).click();await wait(()=>port().dataset.historyPortabilityState==='exported','native history download');return true;},
 async picker(){button('Choose history file',port()).click();return true;},
 async selected(){await pause(60);await wait(()=>['ready','CORRUPT','INCOMPATIBLE','LIMIT'].includes(port().dataset.historyPortabilityState),'native file selection');return{status:port().dataset.historyPortabilityState,text:port().textContent};},
 async selectSynthetic(base64){button('Choose history file',port()).click();const input=await wait(()=>document.querySelector('[aria-label="Standalone analysis history file"]'),'picker'),transfer=new DataTransfer();transfer.items.add(new File([Uint8Array.from(atob(base64),c=>c.charCodeAt(0))],'misleading.bin'));input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));return this.selected();},
 async beginFile(base64){button('Choose history file',port()).click();const input=await wait(()=>document.querySelector('[aria-label="Standalone analysis history file"]'),'picker'),transfer=new DataTransfer();transfer.items.add(new File([Uint8Array.from(atob(base64),c=>c.charCodeAt(0))],'delayed.bin'));input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));return true;},
 async importReview(){const action=await wait(()=>{const b=button('Import history as new project…',port());return b&&!b.disabled?b:null;},'ready import button');action.click();await wait(()=>document.querySelector('dialog[open]'),'explicit new-project confirmation');check(document.activeElement.textContent==='Cancel','Cancel-first focus');return document.querySelector('dialog h2').textContent;},
 async confirm(accept=true){const dialog=document.querySelector('dialog[open]');check(dialog,'open review');button(accept?'Confirm':'Cancel',dialog).click();await pause(200);return{resume:document.querySelector('[data-resume-state]')?.dataset.resumeState,status:port()?.dataset.historyPortabilityState,text:document.body.textContent.slice(-4500)};},
 async waitImported(){await wait(()=>document.querySelector('[data-resume-state]')?.dataset.resumeState==='RESTORE_AVAILABLE','history Resume available');return{...(await store.readResumePreferences()),mounted:Boolean(document.querySelector('[data-workspace-storage]'))};},
 async rootless(id){const p=await store.readProject(id);await store.deleteWorkspace(id,p.revision);await window.s8b.reload();return summary(id);},
 async stageDecode(base64){try{return{count:(await decodeHistoryPortable(Uint8Array.from(atob(base64),c=>c.charCodeAt(0)))).value.records.length};}catch(e){return{error:e.code};}},
 async staleDelete(id){const p=await store.readProject(id),session=createProjectSession(store,p),review=await session.captureDestructive(id,'history',{kind:'clear'});return{review,session};},
 async preference(value){const toggle=document.querySelector('[aria-label="Resume previous workspace automatically"]');check(toggle,'startup preference control');if(toggle.checked!==value)toggle.click();await wait(async()=>(await store.readResumePreferences()).autoResume===value,'acknowledged startup preference');await pause(100);return store.readResumePreferences();},
 async chooseOnly(id){const select=document.querySelector('[aria-label="Saved workspace"]');Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'value').set.call(select,id);select.dispatchEvent(new Event('change',{bubbles:true}));await wait(()=>document.querySelector('[data-resume-state]').dataset.resumeState==='RESTORE_AVAILABLE','choose without mount');return true;},
 async rejectStaleDelete(id){const p=await store.readProject(id),session=createProjectSession(store,p),review=await session.captureDestructive(id,'history',{kind:'clear'});await store.saveThread(id,p.revision,(await store.load(id)).record);try{await session.clearReviewed(review,'history',{kind:'clear'});return false;}catch(e){return e.code==='CONFLICT';}},
 async faultWrite(number){fault=number?{write:number}:null;writeCount=0;return true;},
 async nativeAbort(base64){const stage=await stageAnalysisHistory(Uint8Array.from(atob(base64),c=>c.charCodeAt(0))),originalPut=IDBObjectStore.prototype.put;IDBObjectStore.prototype.put=function(value,...args){const req=originalPut.call(this,value,...args);if(this.name==='analysisHistories'){const tx=this.transaction;req.addEventListener('success',()=>tx.abort(),{once:true});}return req;};try{await store.importAnalysisHistory(stage);return false;}catch(e){return e.code;}finally{IDBObjectStore.prototype.put=originalPut;}},
 async versionchange(){let seen=null;store.subscribe?.(e=>{seen=e.code;});await store.readResumePreferences();const req=indexedDB.open('hypergraph-studio-projects',6);await new Promise((resolve,reject)=>{req.onsuccess=()=>{req.result.close();resolve();};req.onerror=()=>reject(req.error);});try{await store.readResumePreferences();return{seen,read:'unexpected'};}catch(e){return{seen,read:e.code};}},
 async historyState(){const id=(await store.readResumePreferences()).selectedProjectId??(await store.defaultProject()).projectId;return{projectId:id,summary:await summary(id),resume:document.querySelector('[data-resume-state]')?.dataset.resumeState,historyRow:[...document.querySelectorAll('dt')].find(x=>x.textContent==='Analysis history')?.nextElementSibling?.textContent,portability:port()?.textContent,network:window.s8b.network,errors:window.s8b.errors};},
};
console.log('S8C_PAGE_READY');
